import logging
import os
import sys
from pathlib import Path
from typing import Any, Iterable

from apideck_unify import Apideck


PROJECT_DIR = Path(__file__).resolve().parent
USERS_JSON = PROJECT_DIR / "users.json"
OUTPUT_LOG = PROJECT_DIR / "output.log"
SERVICE_ID = "github"


def require_env(name: str) -> str:
    value = os.getenv(name)
    if not value:
        raise RuntimeError(f"Missing required environment variable: {name}")
    return value


def get_field(obj: Any, field: str) -> Any:
    if isinstance(obj, dict):
        return obj.get(field)
    return getattr(obj, field, None)


def to_plain_object(obj: Any) -> Any:
    """Convert SDK model objects to Python containers where possible."""
    if obj is None or isinstance(obj, (str, int, float, bool)):
        return obj
    if isinstance(obj, list):
        return [to_plain_object(item) for item in obj]
    if isinstance(obj, tuple):
        return [to_plain_object(item) for item in obj]
    if isinstance(obj, dict):
        return {key: to_plain_object(value) for key, value in obj.items()}
    if hasattr(obj, "model_dump"):
        return obj.model_dump(mode="json")
    if hasattr(obj, "dict"):
        return obj.dict()
    if hasattr(obj, "to_dict"):
        return obj.to_dict()
    if hasattr(obj, "__dict__"):
        return {
            key: to_plain_object(value)
            for key, value in vars(obj).items()
            if not key.startswith("_")
        }
    return obj


def normalize_optional_string(value: Any) -> str | None:
    if value is None:
        return None
    if isinstance(value, str):
        return value if value else None
    return str(value)


def normalize_user(user: Any) -> dict[str, str | None]:
    user_obj = to_plain_object(user)
    user_id = normalize_optional_string(get_field(user_obj, "id"))
    if not user_id:
        raise RuntimeError(f"Encountered user without a non-empty id: {user_obj!r}")

    return {
        "id": user_id,
        "name": normalize_optional_string(get_field(user_obj, "name")),
        "first_name": normalize_optional_string(get_field(user_obj, "first_name")),
        "last_name": normalize_optional_string(get_field(user_obj, "last_name")),
        "email": normalize_optional_string(get_field(user_obj, "email")),
    }


def page_data(page: Any) -> Iterable[Any]:
    data = get_field(page, "data")
    if data is None:
        return []
    return data


def configure_logging() -> None:
    logging.basicConfig(
        filename=OUTPUT_LOG,
        filemode="w",
        level=logging.INFO,
        format="%(asctime)s %(levelname)s %(message)s",

